27	// Cached agents to avoid recreating on every request.
28	// Keep separate entries per resolved connection count so overlapping requests
29	// with different request-scoped concurrency caps do not evict each other.
30	// Without caching, concurrent requests race on setGlobalDispatcher(),
31	// corrupting TLS session state and producing "bad record mac" errors.
32	//
33	// Note: TLS options (rejectUnauthorized, CA cert) are captured at agent
34	// creation time. This is acceptable because these env vars don't change
35	// mid-process. If that assumption changes, add cache-invalidation logic.
36	const cachedAgents: Map<number, Dispatcher> = new Map();
37	const cachedProxyAgents: Map<string, Dispatcher> = new Map();
38	
39	/**
40	 * Get the connection pool size for HTTP agents.
41	 * Priority: PROMPTFOO_FETCH_CONNECTIONS env var > CLI -j flag > DEFAULT_MAX_CONCURRENCY (4).
42	 * Set PROMPTFOO_FETCH_CONNECTIONS to override independently of eval concurrency
43	 * (e.g., server deployments that need more connections than the default 4).
44	 */
45	function getConnectionPoolSize(): number {
46	  const envConnections = getEnvString('PROMPTFOO_FETCH_CONNECTIONS');
47	  if (envConnections != null) {
48	    const parsed = parseInt(envConnections, 10);
49	    if (!isNaN(parsed)) {
50	      return parsed;
51	    }
52	  }
53	  return cliState.maxConcurrency || DEFAULT_MAX_CONCURRENCY;
54	}
55	
56	/**
57	 * Clear cached agents so the next request creates fresh ones.
58	 * Exported for testing only.
59	 */
60	export function clearAgentCache(): void {
61	  for (const agent of cachedAgents.values()) {
62	    if (typeof agent.close === 'function') {
63	      agent.close();
64	    }
65	  }
66	  cachedAgents.clear();
67	  for (const agent of cachedProxyAgents.values()) {
68	    if (typeof agent.close === 'function') {
69	      agent.close();
70	    }
71	  }
72	  cachedProxyAgents.clear();
73	}
74	
75	function getOrCreateAgent(tlsOptions: ConnectionOptions): Dispatcher {
76	  const concurrency = getConnectionPoolSize();
77	  const existing = cachedAgents.get(concurrency);
78	  if (existing) {
79	    return existing;
80	  }
81	  const agent = new Agent({
82	    headersTimeout: getRequestTimeoutMs(),
83	    keepAliveTimeout: 30_000,
84	    keepAliveMaxTimeout: 60_000,
85	    connections: concurrency,
86	    connect: tlsOptions,
87	  }).compose(interceptors.decompress({ skipErrorResponses: false }));
88	  cachedAgents.set(concurrency, agent);
89	  return agent;
90	}
91	
92	function getProxyAgentCacheKey(proxyUrl: string, concurrency: number): string {
93	  return `${proxyUrl}::${concurrency}`;
94	}
95	
96	function getOrCreateProxyAgent(proxyUrl: string, tlsOptions: ConnectionOptions): Dispatcher {
97	  const concurrency = getConnectionPoolSize();
98	  const cacheKey = getProxyAgentCacheKey(proxyUrl, concurrency);
99	  const existing = cachedProxyAgents.get(cacheKey);
100	  if (existing) {
101	    return existing;
102	  }
103	  const agent = new ProxyAgent({
104	    uri: proxyUrl,
105	    proxyTls: tlsOptions,
106	    requestTls: tlsOptions,
107	    headersTimeout: getRequestTimeoutMs(),
108	    keepAliveTimeout: 30_000,
109	    keepAliveMaxTimeout: 60_000,
110	    connections: concurrency,
111	  }).compose(interceptors.decompress({ skipErrorResponses: false }));
112	  cachedProxyAgents.set(cacheKey, agent);
113	  return agent;
114	}
