116	/**
117	 * Resolve whether to disable transient-error retries. An explicit caller flag
118	 * always wins (a caller may opt back in even when the provider set
119	 * `maxRetries: 0`); otherwise we disable only when the retry context carries
120	 * `maxRetries === 0`.
121	 */
122	function resolveTransientRetryDisabled(explicit?: boolean): boolean {
123	  if (explicit !== undefined) {
124	    return explicit;
125	  }
126	  return getFetchRetryContextMaxRetries() === 0;
127	}
