129	function headersInitToRecord(headers: HeadersInit | undefined): Record<string, string> {
130	  if (!headers) {
131	    return {};
132	  }
133	
134	  if (headers instanceof Headers) {
135	    return Object.fromEntries(headers.entries());
136	  }
137	
138	  if (Array.isArray(headers)) {
139	    return Object.fromEntries(new Headers(headers).entries());
140	  }
141	
142	  return { ...headers };
143	}
