145	export function getFetchWithProxyHeaders(
146	  url: RequestInfo,
147	  options: FetchOptions,
148	): Record<string, string> {
149	  const requestHeaders =
150	    url instanceof Request && options.headers === undefined ? headersInitToRecord(url.headers) : {};
151	  const optionHeaders = headersInitToRecord(options.headers);
152	
153	  return {
154	    ...requestHeaders,
155	    ...optionHeaders,
156	    'x-promptfoo-version': VERSION,
157	  };
158	}
