160	function getFetchUrlString(url: RequestInfo): string | undefined {
161	  if (typeof url === 'string') {
162	    return url;
163	  }
164	  if (url instanceof URL) {
165	    return url.toString();
166	  }
167	  if (url instanceof Request) {
168	    return url.url;
169	  }
170	  return undefined;
171	}
