173	export async function fetchWithProxy(
174	  url: RequestInfo,
175	  options: FetchOptions = {},
176	  abortSignal?: AbortSignal,
177	): Promise<Response> {
178	  let finalUrl = url;
179	  let finalUrlString = getFetchUrlString(url);
180	
181	  if (!finalUrlString) {
182	    throw new Error('Invalid URL');
183	  }
184	
185	  // Combine abort signals: incoming abortSignal parameter + any signal in options
186	  const combinedSignal = abortSignal
187	    ? options.signal
