94	/**
95	 * Sanitizes runtime options to ensure only JSON-serializable data is persisted or exported.
96	 * Removes non-serializable fields like AbortSignal, functions, and symbols.
97	 */
98	export function sanitizeRuntimeOptions(
99	  options?: Partial<import('../types').EvaluateOptions>,
100	): Partial<import('../types').EvaluateOptions> | undefined {
101	  if (!options) {
102	    return undefined;
103	  }
104	
105	  // Create a copy to avoid mutating the original options object.
106	  const sanitized = { ...options };
107	
108	  delete sanitized.abortSignal;
109	
110	  const sanitizedEntries = sanitized as Record<string, unknown>;
111	  for (const [key, value] of Object.entries(sanitizedEntries)) {
112	    if (typeof value === 'function' || typeof value === 'symbol') {
113	      delete sanitizedEntries[key];
114	    }
115	  }
116	
117	  return sanitized;
118	}
