120	/**
121	 * Check if a value looks like a secret based on common patterns.
122	 * Detects API keys, tokens, and other credential patterns.
123	 */
124	export function looksLikeSecret(value: string): boolean {
125	  if (typeof value !== 'string') {
126	    return false;
127	  }
128	
129	  // OpenAI API keys (sk-...)
130	  if (/^sk-[a-zA-Z0-9-_]{20,}/.test(value)) {
131	    return true;
132	  }
133	
134	  // OpenAI project keys (sk-proj-...)
135	  if (/^sk-proj-[a-zA-Z0-9-_]{20,}/.test(value)) {
136	    return true;
137	  }
138	
139	  // Anthropic keys (sk-ant-...)
140	  if (/^sk-ant-[a-zA-Z0-9-_]{20,}/.test(value)) {
141	    return true;
142	  }
143	
144	  // Generic API key patterns (key-...)
145	  if (/^key-[a-zA-Z0-9]{20,}/.test(value)) {
146	    return true;
147	  }
148	
149	  // Bearer tokens
150	  if (/^Bearer\s+.{20,}/i.test(value)) {
151	    return true;
152	  }
153	
154	  // Basic auth
155	  if (/^Basic\s+.{20,}/i.test(value)) {
156	    return true;
157	  }
158	
159	  // Long base64-like strings (likely tokens/keys) - 64+ chars of alphanumeric
160	  // Using 64 chars to reduce false positives on concatenated IDs, base64 content, or long model names
161	  if (/^[a-zA-Z0-9+/=_-]{64,}$/.test(value)) {
162	    return true;
163	  }
164	
165	  // AWS-style access keys (AKIA...)
166	  if (/^AKIA[A-Z0-9]{16}/.test(value)) {
167	    return true;
168	  }
169	
170	  // Google API keys (AIza...)
171	  if (/^AIza[a-zA-Z0-9_-]{35}/.test(value)) {
172	    return true;
173	  }
174	
175	  return false;
176	}
