181	function isClassInstance(obj: any): boolean {
182	  const proto = Object.getPrototypeOf(obj);
183	  // Bail out early if proto is null or Object.prototype
184	  if (!proto || proto === Object.prototype) {
185	    return false;
186	  }
187	  const hasMethods = Object.getOwnPropertyNames(proto).some(
188	    (prop) => prop !== 'constructor' && typeof proto[prop] === 'function',
189	  );
190	  return hasMethods;
191	}
