208	    .split('&')
209	    .map((parameter) => {
210	      const equalsIndex = parameter.indexOf('=');
211	      const encodedName = equalsIndex === -1 ? parameter : parameter.slice(0, equalsIndex);
212	      let name: string;
213	      try {
214	        name = decodeURIComponent(encodedName.replace(/\+/g, ' '));
215	      } catch {
