221	      }
222	
223	      redacted = true;
224	      return `${encodedName}=${encodeURIComponent(REDACTED)}`;
225	    })
226	    .join('&');
227	
228	  return redacted
229	    ? `${value.slice(0, queryStart + 1)}${sanitizedQuery}${value.slice(queryEnd)}`
230	    : value;
231	}
