4	import { CONSENT_ENDPOINT, EVENTS_ENDPOINT, R_ENDPOINT } from '../../constants';
5	import { CLOUD_API_HOST, cloudConfig } from '../../globalConfig/cloud';
6	import logger, { logRequestResponse } from '../../logger';
