21	/**
22	 * Enhanced fetch wrapper that adds logging, authentication, error handling, and optional compression
23	 */
24	
25	export function isPromptfooCloudApiHost(url: string | URL | Request): boolean {
26	  try {
27	    const targetUrl = url instanceof Request ? url.url : url.toString();
28	    return new URL(targetUrl).origin === CLOUD_API_HOST;
29	  } catch {
30	    return false;
31	  }
32	}
