34	export async function monkeyPatchFetch(
35	  url: string | URL | Request,
36	  options?: FetchOptions,
37	): Promise<Response> {
38	  const NO_LOG_URLS = [R_ENDPOINT, CONSENT_ENDPOINT, EVENTS_ENDPOINT];
39	  const headers = (options?.headers as Record<string, string>) || {};
40	  const isSilent = headers['x-promptfoo-silent'] === 'true';
41	  const logEnabled = !NO_LOG_URLS.some((logUrl) => url.toString().startsWith(logUrl)) && !isSilent;
42	
43	  const opts: RequestInit = {
44	    ...options,
45	  };
46	
47	  const originalBody = opts.body;
48	
49	  // Handle compression if requested
50	  if (options?.compress && opts.body && typeof opts.body === 'string') {
51	    try {
52	      const compressed = await gzipAsync(opts.body);
53	      opts.body = compressed as BodyInit;
54	      opts.headers = {
55	        ...(opts.headers || {}),
56	        'Content-Encoding': 'gzip',
57	      };
58	    } catch (e) {
59	      logger.warn(`Failed to compress request body: ${e}`);
60	    }
61	  }
62	
63	  if (isPromptfooCloudApiHost(url)) {
64	    const token = cloudConfig.getApiKey();
65	    opts.headers = {
66	      ...(opts.headers || {}),
67	      ...(token ? { Authorization: `Bearer ${token}` } : {}),
68	    };
69	  }
70	  try {
71	    // biome-ignore lint/style/noRestrictedGlobals: we need raw fetch here
72	    const response = await fetch(url, opts);
73	
74	    if (logEnabled) {
75	      void logRequestResponse({
76	        url: url.toString(),
77	        requestBody: originalBody,
78	        requestMethod: opts.method || 'GET',
79	        response,
80	      });
81	    }
82	
83	    return response;
84	  } catch (e) {
85	    if (logEnabled) {
86	      void logRequestResponse({
87	        url: url.toString(),
88	        requestBody: opts.body,
89	        requestMethod: opts.method || 'GET',
90	        response: null,
91	      });
92	      if (isConnectionError(e as Error)) {
93	        logger.debug(
94	          `Connection error, please check your network connectivity to the host: ${url} ${process.env.HTTP_PROXY || process.env.HTTPS_PROXY ? `or Proxy: ${process.env.HTTP_PROXY || process.env.HTTPS_PROXY}` : ''}`,
95	        );
96	        throw e;
97	      }
98	      logger.debug(
99	        `Error in fetch: ${JSON.stringify(e, Object.getOwnPropertyNames(e), 2)} ${e instanceof Error ? e.stack : ''}`,
100	      );
101	    }
102	    throw e;
103	  }
104	}
