233	function renderRawRequestWithNunjucks(template: string, vars: Record<string, any>): string {
234	  // Protect literal Nunjucks syntax in the source by raw-wrapping
235	  // and then re-enabling only variable tags.
236	  const VAR_TOKEN = '__PF_VAR__';
237	  let working = template;
238	
239	  // 1) Temporarily replace all {{...}} occurrences with placeholders
240	  const placeholders: string[] = [];
241	  working = working.replace(/\{\{[\s\S]*?\}\}/g, (m) => {
