243	    return `${VAR_TOKEN}${idx}__`;
244	  });
245	
246	  // 2) Wrap everything in raw so Nunjucks ignores any {%...%} found in headers/cookies
247	  working = `{% raw %}${working}{% endraw %}`;
248	
249	  // 3) Re-enable variables by inserting endraw/raw around each placeholder
250	  working = working.replace(new RegExp(`${VAR_TOKEN}(\\d+)__`, 'g'), (_m, g1) => {
251	    const original = placeholders[Number(g1)];
252	    return `{% endraw %}${original}{% raw %}`;
253	  });
254	
255	  // 4) Render with Nunjucks normally
256	  const nunjucks = getNunjucksEngine();
257	  return nunjucks.renderString(working, vars);
258	}
