 * Header names whose values must be redacted before fingerprinting so that
 * rotating credentials does not change the derived provider ID. Matches
 * (case-insensitively) Authorization, Cookie, Proxy-Authorization, X-Api-Key,
 * X-Auth-Token, X-Access-Token, X-Secret, X-Signature, and Bearer.
 */
const SENSITIVE_HEADER_PATTERN =
  /(authorization|cookie|proxy-authorization|x-api-key|x-auth-token|x-access-token|x-secret|x-signature|bearer)/i;

/**
 * Recursively sort object keys so that structurally identical configs produce
 * the same serialization regardless of key insertion order.
 */
function canonicalize(value: any): any {
  if (Array.isArray(value)) {
    return value.map(canonicalize);
  }
  if (value && typeof value === 'object') {
    const sorted: Record<string, any> = {};
    for (const key of Object.keys(value).sort()) {
      sorted[key] = canonicalize(value[key]);
    }
    return sorted;
  }
  return value;
}

/**
 * Replace sensitive header values with a stable redacted sentinel. The header
 * name (key) is preserved so that presence vs absence of a sensitive header
 * still differentiates fingerprints.
 */
function redactSensitiveHeaders(
  headers: Record<string, string> | undefined,
): Record<string, string> | undefined {
  if (!headers) {
    return undefined;
  }
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(headers)) {
    result[key] = SENSITIVE_HEADER_PATTERN.test(key) ? REDACTED : value;
  }
  return result;
}

/**
 * Compute a stable, credential-safe fingerprint for a webhook provider. The
 * fingerprint is stable across config key ordering and independent of rotating
 * secret header values, but differentiates URL, method, body, non-sensitive
 * headers, and transformResponse.
 */
function computeFingerprint(url: string, config: N8nProviderConfig): string {
  const fingerprintInput = {
    url,
    method: (config.method || 'POST').toUpperCase(),
    body: config.body ?? null,
    headers: redactSensitiveHeaders(config.headers) ?? null,
    transformResponse:
